// T13.2 — field mapping only (no business / lead / notify / AI logic)
const item = $input.first().json;
const body = item.body ?? item;

const businessId =
  body.business_id ??
  (typeof $env !== 'undefined' && $env.ALPSTEIN_TEST_BUSINESS_ID
    ? $env.ALPSTEIN_TEST_BUSINESS_ID
    : 'demo_barbershop_001');

const phone = body.customer?.phone ?? body.phone ?? null;
const externalCustomerId =
  body.customer?.external_customer_id ?? body.external_customer_id ?? null;

if (!phone && !externalCustomerId) {
  throw new Error(
    'Validation: customer.phone or customer.external_customer_id is required'
  );
}

const text = body.message?.text ?? body.text ?? null;
if (!text || String(text).trim() === '') {
  throw new Error('Validation: message.text is required');
}

const externalMessageId =
  body.message?.external_message_id ?? body.external_message_id ?? null;

const name = body.customer?.name ?? body.name ?? null;
const email = body.customer?.email ?? body.email ?? null;
const timestamp =
  body.message?.timestamp ?? body.timestamp ?? new Date().toISOString();

function sanitizeRawPayload(value) {
  if (value == null || typeof value !== 'object') {
    return {};
  }
  const secretPattern =
    /^(token|secret|password|authorization|api[_-]?key)$/i;
  if (Array.isArray(value)) {
    return value.map((entry) =>
      typeof entry === 'object' && entry !== null
        ? sanitizeRawPayload(entry)
        : entry
    );
  }
  const out = {};
  for (const [key, val] of Object.entries(value)) {
    if (secretPattern.test(key)) {
      out[key] = '[REDACTED]';
    } else if (typeof val === 'object' && val !== null) {
      out[key] = sanitizeRawPayload(val);
    } else {
      out[key] = val;
    }
  }
  return out;
}

const rawSource =
  body.message?.raw_payload ?? body.raw_payload ?? body;
const sanitizedRaw = sanitizeRawPayload(rawSource);

const normalized = {
  business_id: businessId,
  channel: 'test',
  customer: {
    phone,
    name,
    email,
    external_customer_id: externalCustomerId,
  },
  message: {
    text: String(text).trim(),
    external_message_id: externalMessageId,
    timestamp,
    raw_payload: sanitizedRaw,
  },
};

return [{ json: normalized }];

// T13.3 — safe error envelope only; do not expose URL, token, or backend stack traces
return [
  {
    json: {
      success: false,
      error: {
        code: 'N8N_BACKEND_REQUEST_FAILED',
        message: 'Backend request failed',
      },
    },
  },
];

// T13.4 — test-channel customer reply only (no lead/notify/internal envelope)
const backend = $input.first().json;

if (backend.success !== true || !backend.data) {
  return [
    {
      json: {
        success: false,
        error: {
          code: backend.error?.code || 'BACKEND_RESPONSE_FAILED',
          message: backend.error?.message || 'Backend request was not successful',
        },
      },
    },
  ];
}

const shaped = {
  success: true,
  reply_to_customer: backend.data.reply_to_customer || '',
};

if (
  backend.data.message &&
  typeof backend.data.message.is_duplicate === 'boolean'
) {
  shaped.message = { is_duplicate: backend.data.message.is_duplicate };
}

return [{ json: shaped }];

// T13.5 — Telegram-safe owner alert (backend from POST Backend; customer text from Normalize only)
const backend = $('POST Backend').first().json;
const data = backend.data || {};
const notification = data.notification || {};
const normalized = $('Normalize Test Payload').first().json;

const customerText = normalized?.message?.text?.trim() || null;
const customerName = normalized?.customer?.name || null;
const leadStatus = data.lead?.status || null;
const leadPriority = data.lead?.priority || null;
const convStatus = data.conversation?.status || null;

const type = notification.notification_type || 'system_error';
const reason = notification.reason || 'unknown';
const priority = notification.priority || 'normal';

const TYPE_LABELS = {
  new_lead: 'New lead',
  urgent_lead: 'Urgent lead',
  human_handoff: 'Human handoff',
  ai_failure: 'AI failure',
  system_error: 'System alert',
};

const lines = [
  `[Alpstein] ${TYPE_LABELS[type] || TYPE_LABELS.system_error}`,
  `Type: ${type}`,
  `Priority: ${priority}`,
  `Reason: ${reason}`,
];

if (customerName) {
  lines.push(`Customer: ${customerName}`);
}
if (customerText) {
  const snippet =
    customerText.length > 280
      ? customerText.slice(0, 277) + '...'
      : customerText;
  lines.push(`Message: ${snippet}`);
}
if (leadStatus) {
  const lp = leadPriority ? ` (${leadPriority})` : '';
  lines.push(`Lead: ${leadStatus}${lp}`);
}
if (convStatus) {
  lines.push(`Conversation: ${convStatus}`);
}

return [
  {
    json: {
      telegram_text: lines.join('\n'),
      notification_type: type,
    },
  },
];
